const float boxR = 5.;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    vec3 col = vec3(0.);
    float halfBoxR = floor(boxR / 2.);

    // Even numbers result in brighter texture
    // This happens because if boxR is 2 the for loop will go from -1 to 1 (same as 3x3),
    // this makes the square of boxR (4) not match (9)
    //if (mod(boxR, 2.) == 0.) {
    //    boxR += 1.;
    //}

    for (float x = -halfBoxR; x < halfBoxR + 1.; x++) {
        for (float y = -halfBoxR; y < halfBoxR + 1.; y++) {
            vec2 offset = vec2(x, y) / iResolution.xy;
            col += texture(iChannel0, uv + offset).rgb;
        }
    }
    col /= boxR * boxR;


    fragColor = vec4(col, 1.);
}
